from PIL import Image, ImageDraw, ImageFont
import numpy as np
from collections import deque
im=np.array(Image.open('chess_board.png').convert('RGB')).astype(int)
bg1=np.array([240,217,181]); bg2=np.array([181,136,99])

def largest_component(mask):
    H,W=mask.shape; seen=np.zeros_like(mask,bool); best=[]
    for y in range(H):
        for x in range(W):
            if mask[y,x] and not seen[y,x]:
                q=deque([(y,x)]); seen[y,x]=True; comp=[]
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and mask[na,nb] and not seen[na,nb]:
                            seen[na,nb]=True; q.append((na,nb))
                if len(comp)>len(best): best=comp
    out=np.zeros_like(mask,bool)
    for a,b in best: out[a,b]=True
    return out, len(best)

def norm_mask(sub,S=40):
    H,W=sub.shape
    out=np.zeros((S,S),bool)
    for yy in range(S):
        for xx in range(S):
            a=sub[int(yy*H/S):max(int((yy+1)*H/S),int(yy*H/S)+1), int(xx*W/S):max(int((xx+1)*W/S),int(xx*W/S)+1)]
            out[yy,xx]=a.mean()>0.5
    return out

def iou(a,b):
    return (a&b).sum()/max(1,(a|b).sum())

fontpath='/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'
chars={'K':'\u2654','Q':'\u2655','R':'\u2656','B':'\u2657','N':'\u2658','P':'\u2659',
       'k':'\u265A','q':'\u265B','r':'\u265C','b':'\u265D','n':'\u265E','p':'\u265F'}
# render glyph masks at fontsize 60, get bbox mask
templates={}
for size in range(48,70):
  f=ImageFont.truetype(fontpath,size)
  for k,ch in chars.items():
    img=Image.new('L',(120,120),0); ImageDraw.Draw(img).text((10,10),ch,font=f,fill=255)
    a=np.array(img)>128
    ys,xs=np.where(a)
    if len(ys)==0: continue
    sub=a[ys.min():ys.max()+1,xs.min():xs.max()+1]
    templates[(size,k)]=sub

# extract pieces
pieces={}
for r in range(8):
  for c in range(8):
    cell=im[r*80:(r+1)*80, c*80:(c+1)*80]
    dist1=np.abs(cell-bg1).sum(axis=2); dist2=np.abs(cell-bg2).sum(axis=2)
    piece=(np.minimum(dist1,dist2)>60)
    comp,n=largest_component(piece)
    if n<100: continue
    vals=cell[comp]
    blackfrac=((vals.mean(axis=1)<80)).mean(); whitefrac=((vals.mean(axis=1)>235)).mean()
    color='B' if blackfrac>whitefrac else 'W'
    ys,xs=np.where(comp); sub=comp[ys.min():ys.max()+1,xs.min():xs.max()+1]
    pieces[(r,c)]=(color,sub)

for (r,c),(color,sub) in sorted(pieces.items()):
    cands=[]
    for (size,k),t in templates.items():
        # only compare same color category: white outline glyphs uppercase, black filled lowercase
        if color=='W' and not k.isupper(): continue
        if color=='B' and not k.islower(): continue
        # resize both to 40x40 (normalized) and compare
        A=norm_mask(sub,40); B=norm_mask(t,40)
        cands.append((iou(A,B),size,k))
    cands.sort(reverse=True)
    print((r,c),color,'best:',cands[:5])
